# known-bad-5-parity-manylines.sh — regression fixture for the rule-5
# (flag-parity) awk|head SIGPIPE (test-shell-lint exit 141). The --bigflag)
# branch is a value-flag (shift 2) with NO --bigflag=*) parity arm, so it is
# a legitimate finding; the >64KB ;;-free body makes awk stream past head -10
